def parse_duration(s: str) -> int:
    total = 0
    number = ""

    for ch in s:
        if ch.isdigit():
            number += ch
        else:
            if not number:
                raise ValueError(f"Invalid duration: {s!r}")

            value = int(number)
            if ch == "h":
                total += value * 3600
            elif ch == "m":
                total += value * 60
            elif ch == "s":
                total += value
            else:
                raise ValueError(f"Invalid duration: {s!r}")

            number = ""

    if number:
        raise ValueError(f"Invalid duration: {s!r}")

    return total
```

