def rle(s: str) -> str:
    result = []
    prev = None
    count = 0

    for ch in s:
        if ch == prev:
            count += 1
        else:
            if prev is not None:
                result.append(f"{prev}{count}")
            prev = ch
            count = 1

    if prev is not None:
        result.append(f"{prev}{count}")

    return "".join(result)
```

