import re

def top_words(text: str, k: int) -> list[str]:
    if k <= 0:
        return []

    words = [word.lower() for word in re.findall(r"[A-Za-z]+", text)]
    counts: dict[str, int] = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1

    return [word for word, _ in sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:k]]
```

