def luhn_valid(number: str) -> bool:
    digits = []
    for ch in number:
        if ch == " ":
            continue
        if not ch.isdigit():
            return False
        digits.append(int(ch))

    if not digits:
        return False

    total = 0
    for i, digit in enumerate(reversed(digits)):
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
```

